import{_ as i,l as o,o as e,c as s,v as r,p as n,x as t,d,i as p,S as h}from"./chunks/framework.InCnrqk-.js";const A=JSON.parse('{"title":"WFQ","description":"","frontmatter":{"title":"WFQ","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/wfq-fair-queue.md","filePath":"cs/wfq-fair-queue.md","lastUpdated":1789023840000}'),c={name:"cs/wfq-fair-queue.md"};function f(u,a,E,_,P,F){const l=o("Mermaid");return e(),s("div",null,[a[1]||(a[1]=r('<h1 id="wfq" tabindex="-1">WFQ <a class="header-anchor" href="#wfq" aria-label="Permalink to &quot;WFQ&quot;">​</a></h1><div class="epigraph"><p>加权公平排队按权仿真 GPS：每流自己的队列，调度器近似按权分享 $C$，隔离大象与老鼠。</p><footer>—— 据 Demers, Keshav and Shenker, SIGCOMM 1989；Parekh and Gallager, IEEE/ACM ToN 1993 GPS/WFQ 整理</footer></div><p><a href="/cs/cc-fairness-rtt">RTT 不公平</a> 与 <a href="/cs/bufferbloat">缓冲膨胀</a> 指出单队列的病。<a href="/cs/bufferbloat">上一课</a> 点名 FQ-CoDel。缺口是 <strong>WFQ/GPS 对象</strong>：虚时间、权重、与 AIMD 的关系。本课不把令牌桶写完。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>单 FIFO 里短 RTT 大象压死一切。GPS：无穷可分流体按权分带宽。WFQ：包调度近似 GPS，复杂度高；DRR/FQ 是近似。每流隔离后，AIMD 在自己份额里收敛，RTT 偏差不再偷别人的定额。状态：流数 × 队列，ASIC 难，故数据中心少用完整 WFQ，接入网与 Linux qdisc 常见。</p><p>不要把 WFQ 写成「保证延迟上限」除非再加令牌桶准入（Parekh–Gallager）。</p><p><span class="marginnote">DKS 1989。PG 1993 给端到端延迟界条件。本课不证界。</span></p><h3 id="隔离份额" tabindex="-1">隔离份额 <a class="header-anchor" href="#隔离份额" aria-label="Permalink to &quot;隔离份额&quot;">​</a></h3><p>近似 GPS，AIMD 不再互偷。完整延迟界还要整形。每流状态在核心不可扩展，用类或 FQ 近似。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对照 FIFO / PQ / WFQ。画：分类 → 每流队列 → 按虚时间选包。与 ECMP：ECMP 选路径，WFQ 在一跳内分份额。</p>',11)),(e(),n(h,null,{default:t(()=>[p(l,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20CL%5B%22%E5%88%86%E7%B1%BB%E5%88%B0%E6%B5%81%E9%98%9F%E5%88%97%22%5D%20--%3E%20GPS%5B%22%E6%8C%89%E6%9D%83%E4%BB%BF%E7%9C%9F%22%5D%0A%20%20GPS%20--%3E%20OUT%5B%22%E5%87%BA%E7%AB%AF%E5%8F%A3%22%5D%0A%20%20ISO%5B%22%E9%9A%94%E7%A6%BB%22%5D%20--%3E%20AIMD%5B%22%E5%90%84%E6%B5%81%E8%87%AA%E5%B7%B1%E7%9A%84%20AIMD%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<p>方法止于选定对象与对照；机制才说它如何嵌入已有分层与主干课。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>CoDel 可跑在每个 WFQ 队列上。DiffServ 后课用有限类而不是每流，状态少。RoCE 优先级是 PQ 不是 WFQ。5G 切片在无线侧隔离，核心仍可用类排队。</p><p>哈希流识别错误会把两用户捆一队列，隔离失败。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 WF2Q 的全部。令牌桶与整形是下一课。后课默认：每流公平排队隔离份额；完整延迟界还要整形。</p><p>核心路由器按流状态不可扩展，用类或抽样。</p><p>上一课留下的缺口在本课收口；「WFQ」进入后课词汇表后只引用。文献用来钉对象与边界，不把本课写成该主题的独立综述。下一课<a href="/cs/token-bucket-shaping">令牌桶与整形</a>。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>WFQ 近似 GPS 按权分享。</li><li>隔离后 AIMD 不再互偷。</li><li>每流状态是扩展边界。</li><li>后课只引用本课钉死的对象，不从该领域总问题重开。</li><li>出处：Demers et al., 1989；Parekh–Gallager, 1993。</li></ul>',10))])}const S=i(c,[["render",f]]);export{A as __pageData,S as default};
